  if(totalPage == last)
    next = last;
  let prev = currentPage - 1;
  if(prev <= 1)
    prev = 1;

  if(totalPage <= 1){
    first = last;
    next = last;
  }

  console.log("totalPage:"+totalPage+"\npageGroup:"+pageGroup+"\ncurrentPage:"+currentPage+"\nfirst:"+first+"\nlast:"+last+"\nnext:"+next+"\nprev:"+prev);

